(window.DOM_LAMLA=window.DOM_LAMLA||{})["lecture-7"]={"lecture":"lecture-7","chapters":[{"slug":"ecg","must":[{"star":true,"html":"<strong>ECG</strong> records voltage differences from cardiac depolarisation and repolarisation at the skin; it does not directly measure contraction or blood flow."},{"star":false,"html":"<strong>Electrical activation</strong> normally precedes muscle contraction → an ECG complex can appear even when the heart is not pumping effectively."},{"star":false,"html":"<strong>Electrode</strong> means the physical skin contact; a lead is the electrical view calculated from electrode voltages."},{"star":false,"html":"<strong>Twelve-lead ECG</strong> uses ten electrodes to create twelve views; the right-leg electrode reduces electrical interference rather than providing a lead."},{"star":true,"html":"<strong>Depolarisation direction</strong> determines polarity: towards a lead's positive end gives an upward deflection; away gives a downward deflection."},{"star":false,"html":"<strong>Perpendicular depolarisation</strong> produces a small or biphasic deflection because little of the electrical vector points along the lead."},{"star":false,"html":"<strong>Lead II</strong> usually has an upright QRS, while aVR usually has a downward QRS, because they view ventricular depolarisation from different directions."},{"star":false,"html":"<strong>T-wave direction</strong> often matches the QRS because ventricular repolarisation travels in reverse order and has electrical polarity opposite to depolarisation."},{"star":false,"html":"<strong>Standard limb leads</strong> I, II and III are bipolar because each measures voltage between a negative and a positive limb electrode."},{"star":false,"html":"<strong>Lead I</strong> measures right arm negative to left arm positive; its positive viewing direction points towards the left arm."},{"star":false,"html":"<strong>Lead II</strong> measures right arm negative to left leg positive; its positive viewing direction points towards the left leg."},{"star":false,"html":"<strong>Lead III</strong> measures left arm negative to left leg positive; its positive viewing direction points towards the left leg."},{"star":false,"html":"<strong>Einthoven's law</strong> states Lead II = Lead I + Lead III for voltages measured at the same instant."},{"star":false,"html":"<strong>Augmented limb leads</strong> aVR, aVL and aVF view from right arm, left arm and left foot respectively, against an averaged limb reference."},{"star":false,"html":"<strong>Chest leads</strong> V1–V6 view the heart in the horizontal plane, whereas limb leads view it in the frontal plane."},{"star":false,"html":"<strong>V1 and V2</strong> sit at the fourth intercostal space beside the sternum, on the right and left respectively."},{"star":false,"html":"<strong>V4</strong> sits at the fifth intercostal space in the midclavicular line; V3 lies halfway between V2 and V4."},{"star":false,"html":"<strong>V5 and V6</strong> sit level with V4 at the anterior and midaxillary lines respectively; wrong placement can distort the ECG."},{"star":true,"html":"<strong>P wave</strong> represents atrial depolarisation spreading from the SA node; atrial contraction follows the electrical event."},{"star":true,"html":"<strong>PR interval</strong> runs from the start of P to the start of QRS, including atrial activation and delayed conduction towards the ventricles."},{"star":false,"html":"<strong>PR segment</strong> starts at the end of P and stops at the start of QRS; it excludes the P wave itself."},{"star":true,"html":"<strong>QRS complex</strong> represents ventricular depolarisation; its larger amplitude reflects the greater mass of ventricular muscle."},{"star":false,"html":"<strong>Q, R and S</strong> name successive downward, upward and downward deflections; an individual lead may not display all three."},{"star":false,"html":"<strong>Atrial repolarisation</strong> is usually hidden within the much larger QRS complex rather than forming a distinct visible wave."},{"star":false,"html":"<strong>ST segment</strong> runs from the end of QRS to the start of T, while most ventricular muscle is depolarised in its plateau phase."},{"star":false,"html":"<strong>Flat ST segment</strong> does not mean ventricular rest; ischaemia or hypoxia can produce ST elevation or depression."},{"star":false,"html":"<strong>T wave</strong> represents ventricular repolarisation, which normally lasts longer than ventricular depolarisation."},{"star":false,"html":"<strong>U wave</strong> sometimes follows T; the lecture calls it late ventricular repolarisation, although its exact origin is uncertain."},{"star":false,"html":"<strong>QT interval</strong> starts with QRS and ends with T → it spans ventricular depolarisation and repolarisation and shortens as heart rate rises."},{"star":false,"html":"<strong>ECG calibration</strong> at 25 mm/s gives 0.04 s per horizontal millimetre; at 10 mm/mV, each vertical millimetre is 0.1 mV."},{"star":false,"html":"<strong>One large ECG square</strong> is 5 mm → 0.20 s horizontally and 0.5 mV vertically at standard calibration."},{"star":false,"html":"<strong>Heart rate</strong> for a regular rhythm at 25 mm/s equals 1500 divided by small squares, or 300 divided by large squares, between R waves."},{"star":false,"html":"<strong>RR interval</strong> is the time between R waves → heart rate in beats/min equals 60 divided by RR measured in seconds."},{"star":false,"html":"<strong>Irregular rhythms</strong> have unequal RR gaps → counting QRS complexes over six seconds and multiplying by ten gives an average rate."},{"star":false,"html":"<strong>Normal sinus rhythm</strong> passes four checks: rate about 60–100 beats/min at rest, equal RR gaps, a P wave before every QRS, and normal PR and QRS durations."},{"star":false,"html":"<strong>First-degree AV block</strong> prolongs the PR interval beyond 0.20 s while every P wave still conducts to a QRS."},{"star":false,"html":"<strong>Second-degree AV block</strong> causes some P waves to lack a following QRS because some atrial impulses fail to conduct."},{"star":false,"html":"<strong>Third-degree AV block</strong> shows independent P waves and QRS complexes because atrial impulses no longer conduct to the ventricles."},{"star":false,"html":"<strong>ECG and mechanics</strong> differ in timing: P precedes atrial systole, QRS precedes ventricular systole, and T accompanies the transition towards relaxation."}],"numbers":"<table>\n<thead>\n<tr>\n  <th>Value</th>\n  <th>Number</th>\n  <th>Why it matters</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Standard recording speed</td>\n  <td>25 mm/s</td>\n  <td>Converts horizontal distance on the ECG into time.</td>\n</tr>\n<tr>\n  <td>Standard voltage calibration</td>\n  <td>10 mm = 1 mV</td>\n  <td>Converts vertical height into electrical voltage.</td>\n</tr>\n<tr>\n  <td>Small square: time</td>\n  <td>1 mm = 0.04 s</td>\n  <td>Measures intervals and durations at 25 mm/s.</td>\n</tr>\n<tr>\n  <td>Large square: time</td>\n  <td>5 mm = 0.20 s</td>\n  <td>Five large squares represent one second.</td>\n</tr>\n<tr>\n  <td>Small square: voltage</td>\n  <td>1 mm = 0.1 mV</td>\n  <td>Measures wave height at standard calibration.</td>\n</tr>\n<tr>\n  <td>Large square: voltage</td>\n  <td>5 mm = 0.5 mV</td>\n  <td>Converts large vertical grid distances into voltage.</td>\n</tr>\n<tr>\n  <td>Standard ECG contacts and views</td>\n  <td>10 electrodes, 12 leads</td>\n  <td>Ten skin contacts provide twelve electrical perspectives.</td>\n</tr>\n<tr>\n  <td>Bipolar, augmented and chest leads</td>\n  <td>3, 3 and 6</td>\n  <td>Their combined views make up the twelve leads.</td>\n</tr>\n<tr>\n  <td>P-wave duration</td>\n  <td>0.08–0.10 s</td>\n  <td>Duration of atrial depolarisation in the lecture.</td>\n</tr>\n<tr>\n  <td>PR-interval duration</td>\n  <td>0.12–0.20 s</td>\n  <td>Time from atrial depolarisation onset to ventricular depolarisation onset.</td>\n</tr>\n<tr>\n  <td>QRS duration</td>\n  <td>0.06–0.10 s</td>\n  <td>Duration of ventricular depolarisation given in the lecture.</td>\n</tr>\n<tr>\n  <td>QT-interval duration</td>\n  <td>0.20–0.40 s</td>\n  <td>Changes with heart rate because depolarisation and repolarisation take time.</td>\n</tr>\n<tr>\n  <td>Rate shortcut using small squares</td>\n  <td>1500 ÷ small squares</td>\n  <td>Beats/min from consecutive R waves in a regular rhythm at 25 mm/s.</td>\n</tr>\n<tr>\n  <td>Rate shortcut using large squares</td>\n  <td>300 ÷ large squares</td>\n  <td>Equivalent calculation when counting large ECG squares.</td>\n</tr>\n<tr>\n  <td>Resting sinus-rate range</td>\n  <td>About 60–100 beats/min</td>\n  <td>Used for the approved chapter's basic rhythm assessment.</td>\n</tr>\n<tr>\n  <td>First-degree AV block</td>\n  <td>PR greater than 0.20 s</td>\n  <td>Signals are delayed but every P wave still conducts.</td>\n</tr>\n<tr>\n  <td>Irregular-rate estimate</td>\n  <td>QRS count in 6 s × 10</td>\n  <td>Averages the rate instead of using one unequal RR interval.</td>\n</tr>\n</tbody>\n</table>\n","chains":"<ol>\n<li><strong>Recording an ECG</strong>: Cardiac cells depolarise or repolarise → voltage differences spread through tissues → skin electrodes detect differences → leads display electrical traces.</li>\n<li><strong>Lead polarity</strong>: Depolarisation vector points towards a lead's positive end → positive voltage is recorded → ECG deflects upwards; a vector pointing away produces a downward deflection.</li>\n<li><strong>Electrical-to-mechanical sequence</strong>: SA-node activation spreads through atria → P wave → atrial contraction → AV conduction delay → QRS → ventricular contraction → T wave → ventricular relaxation.</li>\n<li><strong>Finding heart rate</strong>: Count 22 small squares between R waves at 25 mm/s → RR = 22 × 0.04 = 0.88 s → 60 ÷ 0.88 ≈ 68 beats/min.</li>\n</ol>\n","confuse":"<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Electrode</strong></th>\n  <th><strong>Lead</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Meaning</td>\n  <td>Physical contact attached to the skin</td>\n  <td>Electrical view calculated from electrode voltages</td>\n</tr>\n<tr>\n  <td>Count in standard ECG</td>\n  <td>Ten</td>\n  <td>Twelve</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>Standard limb lead</strong></th>\n  <th><strong>Augmented limb lead</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Principle</td>\n  <td>Voltage difference between two limb electrodes</td>\n  <td>One positive limb electrode compared with a reference</td>\n</tr>\n<tr>\n  <td>Examples</td>\n  <td>I, II and III</td>\n  <td>aVR, aVL and aVF</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>PR interval</strong></th>\n  <th><strong>PR segment</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Boundaries</td>\n  <td>Start of P to start of QRS</td>\n  <td>End of P to start of QRS</td>\n</tr>\n<tr>\n  <td>Includes P wave?</td>\n  <td>Yes</td>\n  <td>No</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>ST segment</strong></th>\n  <th><strong>QT interval</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Boundaries</td>\n  <td>End of QRS to start of T</td>\n  <td>Start of QRS to end of T</td>\n</tr>\n<tr>\n  <td>Significance</td>\n  <td>Ventricular plateau; usually isoelectric</td>\n  <td>Ventricular depolarisation and repolarisation</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>P wave</strong></th>\n  <th><strong>QRS complex</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Electrical event</td>\n  <td>Atrial depolarisation</td>\n  <td>Ventricular depolarisation</td>\n</tr>\n<tr>\n  <td>Mechanical event that follows</td>\n  <td>Atrial systole</td>\n  <td>Ventricular systole</td>\n</tr>\n</tbody>\n</table>\n<table>\n<thead>\n<tr>\n  <th></th>\n  <th><strong>First-degree AV block</strong></th>\n  <th><strong>Third-degree AV block</strong></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n  <td>Atrial-to-ventricular conduction</td>\n  <td>Delayed; every P conducts</td>\n  <td>Absent; P and QRS are independent</td>\n</tr>\n<tr>\n  <td>ECG clue</td>\n  <td>PR greater than 0.20 s</td>\n  <td>No consistent P–QRS relationship</td>\n</tr>\n</tbody>\n</table>\n","traps":"<ul>\n<li>Trap: <strong>ECG activity</strong> proves the heart is pumping → Truth: It measures electrical activity, so effective blood ejection requires separate assessment.</li>\n<li>Trap: <strong>An upward ECG wave</strong> means the heart moves upwards → Truth: It shows the direction of electrical activity relative to the positive lead.</li>\n<li>Trap: <strong>Ten electrodes</strong> give only ten leads → Truth: One electrode arrangement can generate twelve voltage views.</li>\n<li>Trap: <strong>PR interval</strong> begins after the P wave → Truth: It starts at the beginning of P; the PR segment begins after P ends.</li>\n<li>Trap: <strong>The QRS</strong> is the ventricles contracting → Truth: It is the electrical switch-on of the ventricles; contraction follows it a moment later.</li>\n<li>Trap: <strong>Atrial repolarisation</strong> must form a separate visible ECG wave → Truth: Its small electrical signal is usually buried within QRS.</li>\n<li>Trap: <strong>A flat ST segment</strong> means the ventricles are relaxed → Truth: Ventricular cells are depolarised and mechanically active during the plateau.</li>\n<li>Trap: <strong>QT interval</strong> ends when T begins → Truth: It ends when T finishes because it includes ventricular repolarisation.</li>\n<li>Trap: <strong>One horizontal small square</strong> measures 0.1 mV → Truth: Horizontal distance measures time; voltage is vertical height.</li>\n<li>Trap: <strong>1500 ÷ large squares</strong> gives heart rate → Truth: Use 1500 for small squares and 300 for large squares at 25 mm/s.</li>\n<li>Trap: <strong>One RR gap</strong> reliably estimates an irregular rhythm → Truth: Unequal gaps require averaging over several beats, such as six seconds.</li>\n<li>Trap: <strong>First-degree AV block</strong> means missed ventricular beats → Truth: Every P still produces QRS, but the PR interval is prolonged.</li>\n</ul>\n"}]};
